import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  createMemoryHistory,
} from '@tanstack/react-router';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export const flakyRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/flaky',
  loader: () => {
    throw new Error('boom');
  },
  errorComponent: ({ error }) => <p>err: {(error as Error).message}</p>,
  component: () => <p>flaky-ok</p>,
});

const routeTree = rootRoute.addChildren([flakyRoute]);

export function makeRouter(initialEntries: string[] = ['/flaky']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
